# gen-blog1.ps1 — blog builder + posts 1-5. Pure ASCII.
. "$PSScriptRoot/gen-common.ps1"
function New-Post($slug,$title,$cat,$catslug,$date,$imgk,$excerpt,$body,$faqs,$pkgs,$arts){
  $im=$IMG[$imgk]
  $pcards=""; foreach($p in $pkgs){ $pcards+=Card-Pkg $p[0] $p[1] $p[2] $p[3] $p[4] $imgk }
  $acards=""; foreach($a in $arts){ $acards+=Card-Dest $a[0] $a[1] $a[2] $imgk }
  $b=Crumb @('<a href="/">Home</a>','<a href="/blog/">Blog</a>',$title)
  $b+="<div class=`"hero`"><img class=`"bg`" src=`"$($im[0])`" alt=`"$($im[1])`"><div class=`"hero-in`"><p class=`"eyebrow`">$cat | $date</p><h1>$title</h1></div></div>"
  $b+="<section class=`"block`"><div class=`"wrap`" style=`"max-width:840px`">"
  $b+="<p class=`"meta`">By Safari Specialist Team | Published $date | Category: <a href=`"/blog/category/$catslug/`">$cat</a></p>"
  $b+="<div style=`"background:#f1ebda;border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:18px 0`"><strong>Excerpt:</strong> $excerpt</div>"
  $b+=$body
  if($pcards -ne ""){ $b+="<h2>Related safari packages</h2><div class=`"grid g3`">$pcards</div>" }
  if($acards -ne ""){ $b+="<h2>Related articles</h2><div class=`"grid g3`">$acards</div>" }
  $b+=(Faq-List $faqs)+(CTA-Band "Turn this into an itinerary" "A specialist replies within 24 hours." $title)+"</div></section></main>"
  $canon="https://www.adventuresafariafrica.com/blog/$slug/"
  $html=Shell $title $excerpt $canon $b ('<script type="application/ld+json">{"@context":"https://schema.org","@type":"BlogPosting","headline":"'+$title+'","datePublished":"'+$date+'","author":{"@type":"Organization","name":"Adventure Safari Africa"}}</script>'+(Faq-Schema $faqs))
  New-Item -ItemType Directory -Path "blog/$slug" -Force | Out-Null
  $html | Out-File -FilePath "blog/$slug/index.html" -Encoding utf8
  "post: $slug"
}
New-Post "serengeti-vs-masai-mara" "Serengeti vs Masai Mara: Which Is Better? (Honest 2026 Comparison)" "Great Migration" "great-migration" "2026-06-15" "MIG" "Same ecosystem, different trips: the Mara concentrates wildlife July to October; the Serengeti holds herds ten months with calving and Grumeti exclusives. Choose by month." "<p class=`"lead`">They share one ecosystem and one Migration - but they are different trips. The Mara concentrates; the Serengeti sprawls. Choose by month, crowd tolerance and budget, not by reputation.</p><h2>The short version</h2><table class=`"cmp`"><tr><th></th><th>Serengeti (Tanzania)</th><th>Masai Mara (Kenya)</th></tr><tr><td>Size</td><td>14,750 sq km - vast, zoned</td><td>1,510 sq km - dense, compact</td></tr><tr><td>Migration window</td><td>Herds present about 10 months</td><td>Herds present Jul-Oct</td></tr><tr><td>Exclusive moments</td><td>Calving (Jan-Mar), Grumeti (Jun)</td><td>Peak crossing density (Aug-Oct)</td></tr><tr><td>Crowds</td><td>Dispersed; busy Seronera</td><td>Dense at crossings; conservancies quiet</td></tr><tr><td>Typical 7-day cost</td><td>From $3,450</td><td>From $3,100</td></tr><tr><td>Combines with</td><td>Ngorongoro, Zanzibar, Kilimanjaro</td><td>Amboseli, lakes, Diani beach</td></tr></table><h2>Wildlife: effectively equal, differently staged</h2><p>Same species, same herds. The Mara's density means shorter drives between sightings in season; the Serengeti's scale stages predator-prey drama (calving, Grumeti) the Mara never hosts. Resident cats are superb in both year-round - lions, leopards and cheetahs do not migrate.</p><h2>Migration timing decides</h2><p>January to June: Serengeti only - the Mara has no herds. July to October: both, with the Mara concentrating crossings and the northern Serengeti offering wilder, emptier river frontage. November to December: herds return south; Serengeti again. See the <a href=""/great-migration/month-by-month/"">month-by-month calendar</a>.</p><h2>Crowds and concessions</h2><p>The Mara's reserve roads punish shared vehicles in season - twenty minibuses per crossing. Mara conservancies (Naboisho, Olare Motorogi, Mara North) fix this with bed limits, off-road rights and night drives. The Serengeti's scale disperses crowds naturally, except Seronera in August. Private vehicles plus smart zones beat reputation every time.</p><h2>Cost comparison</h2><p>Kenya typically runs 10-15 percent less for equivalent tiers, mostly on park fees and shorter distances. Tanzania's crater day and Zanzibar combos add value differently - compare line-item quotes, not headlines. Full breakdown: <a href=""/travel-guide/african-safari-cost/"">safari cost guide</a>.</p><h2>How to choose</h2><ul><li><strong>Traveling Jan-Jun?</strong> Serengeti - the Mara has no herds.</li><li><strong>Jul-Oct first safari?</strong> Either; Mara is logistically easier, Serengeti north is wilder.</li><li><strong>Honeymoon or photography?</strong> Whichever offers a private concession in budget.</li><li><strong>Budget?</strong> Kenya edges cheaper; Tanzania's combos add value differently.</li></ul>" @(@{"q"="Can I see the Migration in both?";"a"="July to October, yes. Outside those months only the Serengeti holds herds - the Mara relies on resident game, still excellent for cats."},@{"q"="Which is cheaper?";"a"="Kenya typically 10-15 percent less for equivalent tiers, mostly park fees and distances. Tanzania's crater and Zanzibar combos rebalance value differently."},@{"q"="Which is better for photography?";"a"="The Mara for density and short drives; the Serengeti for calving action and empty river frontage. Conservancy access matters more than the border."},@{"q"="Can we do both in one trip?";"a"="Yes via Isebania in 10-12 day combos, best July to October. Off-season, going deep in one beats splitting."},@{"q"="Which has fewer crowds?";"a"="The Serengeti by scale, except Seronera; the Mara by conservancy choice. Avoid reserve-gate corridors and minibus hours in both."},@{"q"="Which is better for families?";"a"="Kenya edges it: shorter drives, Naivasha activity breaks, Mara fly-ins. Tanzania wins from age eight up with pools and a Zanzibar finish."},@{"q"="Do the same animals live in both?";"a"="Yes - one ecosystem. Resident lions, leopards, elephants and rhinos stay put; only the wildebeest, zebra and gazelle herds migrate."},@{"q"="How many days in each?";"a"="Three nights minimum per side: two locations in three nights beats one base. Seven days total suits one side deeply."},@{"q"="Should we add the crater or Amboseli?";"a"="The crater pairs only with the Serengeti side; Amboseli only with the Mara side. Both add a distinct ecosystem day - take it if days allow."}) @(@("/tanzania-safari/7-day-tanzania-safari/","7-Day Tanzania Safari","7 days | Migration","From $3,450","Serengeti plus crater, herd-positioned."),@("/kenya-safari/7-day-kenya-safari/","7-Day Kenya Safari","7 days | Classic","From $3,100","Mara plus Amboseli and lakes.")) @(@("/blog/best-time-great-migration/","Best Time for the Great Migration","Migration timing: crossings vs calving vs value."),@("/national-parks/serengeti/","Serengeti Park Guide","Zones, seasons and camp strategy."))
New-Post "best-time-great-migration" "Best Time for the Great Migration: Crossings vs Calving vs Value" "Great Migration" "great-migration" "2026-05-20" "MIG" "No single best month: calving January-March for predators and value, Grumeti June for exclusivity, Mara crossings July-October for drama." "<p class=`"lead`">Pick your spectacle first, month second. The herds move with rain, not calendars - and the wrong camp zone in the right month still fails.</p><h2>Calving (Jan-Mar): predators and value</h2><p>Ndutu and the southern Serengeti: 8,000 calves daily, lions and cheetahs hunting in daylight, few vehicles, lower rates. The connoisseur's season and the best photography value in Africa.</p><h2>Grumeti (Jun): exclusivity</h2><p>Western corridor crossings with a fraction of Mara-season vehicles. Remote camps, dramatic river action, superb cats - for second-timers and photographers avoiding crowds.</p><h2>Mara crossings (Jul-Oct): peak drama</h2><p>Northern Serengeti and Masai Mara: herds bunch at crossing points for days, then cross in minutes. Three-plus nights near Kogatende with picnic lunches; patience is the strategy. August-September peak.</p><h2>Shoulder months (Nov-Dec, Apr-May)</h2><p>Herds transit via Seronera; resident game carries the trip; rates drop 20-35 percent. April-May long rains limit some roads - ask about routing.</p><h2>The one rule</h2><p>Camp location beats luck. Mobile camps near the herds see ten times the action of lodges two hours away. See <a href=""/great-migration/month-by-month/"">month-by-month positions</a> and <a href=""/tanzania-migration-safari/"">timed safaris</a>.</p>" @(@{"q"="Which month has the most dramatic crossings?";"a"="August to September at the Mara River, with July building and October trailing. Book Kogatende camps 9-12 months ahead."},@{"q"="Is calving really as good as crossings?";"a"="For sustained action, better: weeks of hunts versus hours of waiting. Photographers and returning visitors overwhelmingly prefer February."},@{"q"="What if rains shift the herds?";"a"="Itineraries built on two zones (e.g. central plus north) insure against timing shifts. Single-zone short trips carry the most timing risk."},@{"q"="How many nights for crossings?";"a"="Three minimum near the river, four-plus in August. Day-trippers from distant lodges see crossings by luck alone."},@{"q"="Kenya or Tanzania for the Migration?";"a"="Same herds: Tanzania holds them ten months with more variety; Kenya concentrates them July-October with easier logistics."},@{"q"="Are crossings guaranteed?";"a"="Never on a given day. Herds bunch, hesitate, sometimes turn back. Three-plus nights converts odds into probability."},@{"q"="What does Migration season cost?";"a"="Peak premiums of 15-25 percent over green season; calving months price between. Mobile camps cost more than lodges but position better."},@{"q"="Can kids enjoy Migration trips?";"a"="Yes with realistic briefings: waiting days bore under-8s. Calving season suits families better than crossing vigils."},@{"q"="Balloon during Migration?";"a"="Superb: dawn flights over herds with bush breakfast. Book at proposal stage - 550 to 600 dollars, seats limited."}) @(@("/tanzania-migration-safari/7-day-migration-safari/","7-Day Migration Safari","7 days | Season-placed","From $3,800","Camp follows the herds."),@("/kenya-safari/7-day-kenya-safari/","7-Day Kenya + Mara Herds","7 days","From $3,600","Mara positioning in season.")) @(@("/blog/serengeti-vs-masai-mara/","Serengeti vs Masai Mara","Which side suits you."),@("/great-migration/month-by-month/","Migration Month by Month","Herd positions Jan-Dec."))
New-Post "how-many-days-safari" "How Many Days Do You Need on Safari? (Country-by-Country Math)" "Safari Planning" "safari-planning" "2026-04-10" "KE" "Tanzania and Kenya 5-7, Uganda 7-10, Botswana 7-8, Namibia 10, South Africa 9 - plus why the last two days add the most." "<p class=`"lead`">Duration math is simple: transit days cost wildlife days. Every itinerary below counts full park days, not airport-to-airport padding.</p><h2>By country</h2><table class=`"cmp`"><tr><th>Destination</th><th>Minimum</th><th>Sweet spot</th><th>Grand</th></tr><tr><td>Tanzania north</td><td>4-5 days</td><td>7 days</td><td>10-14 + Zanzibar</td></tr><tr><td>Kenya</td><td>3 (Mara fly-in)</td><td>7 days</td><td>10 + beach</td></tr><tr><td>Uganda</td><td>3 (gorilla trek)</td><td>7 days</td><td>10-14 grand</td></tr><tr><td>Botswana</td><td>5 days</td><td>8 days</td><td>10-12 + Falls</td></tr><tr><td>Namibia</td><td>7 days</td><td>10 days</td><td>12-14 + coast</td></tr><tr><td>South Africa</td><td>5 (Kruger)</td><td>9 (Cape + Kruger)</td><td>12-14 grand</td></tr></table><h2>Why the last two days add most</h2><p>Days 1-2 acclimatize; days 3-5 deliver icons; days 6-plus deliver patience - full-day crossing waits, second chances on leopards, rest that sharpens eyes. Rushed trips see parks; unhurried trips see behavior.</p><h2>Adding beach, trekking, cities</h2><p>Zanzibar/Diani: plus 3-5 nights. Kilimanjaro: plus 7-9 days. Cape Town: plus 3-4 nights. Gorilla permits: fixed dates anchor the whole itinerary - book them first.</p>" @(@{"q"="Is 4 days enough for Tanzania?";"a"="As a taste: Tarangire, crater, one Serengeti day with a long transit. Five transforms it with a second Serengeti day."},@{"q"="How long for gorillas plus savanna?";"a"="Seven minimum:chimps, lions and gorillas. Three covers a fly-in trek only."},@{"q"="Do travel days count?";"a"="We quote park days honestly: arrival and departure days are logistics, not safari. Ask any operator which days include game drives."},@{"q"="Longer or more luxurious?";"a"="Longer, almost always: two extra mid-range days beat one suite night for sightings. Upgrade tier after duration is right."},@{"q"="How many beach nights?";"a"="Three minimum, four to five ideal. Two is a tease after safari dust."},@{"q"="Can we split two countries in 10 days?";"a"="Kenya plus Tanzania works at 10 (not 7): Mara, Serengeti, crater with border handling. Shorter splits waste days in transit."},@{"q"="What about jet lag?";"a"="Add a pre-night after long-haul arrivals. Day-one game drives after red-eyes underperform - rest first."},@{"q"="School-holiday constraints?";"a"="June-August and December-January align with dry seasons in East Africa - book 9-12 months ahead for family rooms."},@{"q"="Ask before booking?";"a"="Which days are full game-drive days, where are overnights, and what is driving versus flying time daily. Vague answers hide windscreen safaris."}) @(@("/tanzania-safari/7-day-tanzania-safari/","7-Day Tanzania Safari","7 days","From $3,450","The sweet-spot week."),@("/kenya-safari/7-day-kenya-safari/","7-Day Kenya Safari","7 days","From $3,100","Classic loop, unhurried.")) @(@("/blog/best-time-great-migration/","Best Migration Timing","Match month to days."),@("/travel-guide/african-safari-cost/","Safari Cost Guide","Budget per day."))
"blog1 done"
